cd reports && python3 - <<'EOF'
import re, glob, os, json
data={}
for f in sorted(glob.glob('*.md')):
    txt=open(f).read()
    wid=os.path.basename(f)[:3].upper()
    reg=None
    for pat in [r'Region:\s*(\w+)', r'sits in the (\w+) region', r'A (\w+)-region site']:
        m=re.search(pat,txt,re.I)
        if m: reg=m.group(1); break
    mgr=None
    for pat in [r'Site manager:\s*(.+)', r'Managed by\s*(.+)', r'(.+?) runs the floor here']:
        m=re.search(pat,txt)
        if m: mgr=m.group(1).strip(); break
    yr=None
    for pat in [r'Opened in (\d{4})', r'Operating since (\d{4})', r'Commissioned (\d{4})']:
        m=re.search(pat,txt,re.I)
        if m: yr=int(m.group(1)); break
    stock={}
    sec=txt.split('## Stock on hand')[1].split('## Notes')[0]
    for line in sec.splitlines():
        line=line.strip().lstrip('- ').strip()
        if not line: continue
        m=re.match(r'SKU-(\w+):\s*(\d+)$',line) or \
          re.match(r'(\d+)\s+units of SKU-(\w+)$',line) or \
          re.match(r'stock of SKU-(\w+) is (\d+)$',line) or \
          re.match(r'SKU-(\w+) \((\d+) units\)$',line)
        if m:
            if line[0].isdigit(): stock[m.group(2)]=int(m.group(1))
            else: stock[m.group(1)]=int(m.group(2))
        else:
            print('UNPARSED',f,repr(line))
    data[wid]=dict(region=reg,manager=mgr,year=yr,stock=stock)
print('files parsed',len(data))
for k,v in data.items():
    if not all([v['region'],v['manager'],v['year']]): print('MISSING',k,v)
json.dump(data,open('/tmp/data.json','w'),indent=1)
print('q1', sum(v['stock'].get('A9',0) for v in data.values()))
c3={k:v['stock'].get('C3',0) for k,v in data.items()}
mx=max(c3.values()); print('q2', [k for k,x in c3.items() if x==mx], mx)
print('q3', sum(1 for v in data.values() if v['region'].lower()=='north'))
old=sorted(data.items(), key=lambda kv: kv[1]['year'])[:4]
print('q4', [(k,v['year'],repr(v['manager'])) for k,v in old])
print('q5', sorted(k for k,v in data.items() if 'Z1' in v['stock']))
east={k:v['stock'].get('B2',0) for k,v in data.items() if v['region'].lower()=='east'}
print('q6', sorted(east.items()), 'n=',len(east), 'mean=', round(sum(east.values())/len(east),1))
print('B2 missing:', [k for k,v in data.items() if 'B2' not in v['stock']])
print('regions:', sorted(set(v['region'] for v in data.values())))
EOF

